## PLAN STRUCTURE (8 atomic fixes, apply_order numbered)

### FIX 1: CREATE project/instance-health.ts (~55 lines)
New Context.Service with Ref<Map<string, InstanceStatus>>. Mirrors HealthRegistry pattern exactly.

```typescript
import { Context, Effect, Layer, Ref } from "effect"

export enum InstanceStatus {
  Booting = "booting",
  Ready = "ready",
  Degraded = "degraded",
  Failed = "failed",
  Disposed = "disposed",
}

export interface InstanceHealth {
  status: InstanceStatus
  failures?: string[]
  updatedAt: number
}

export interface Interface {
  readonly get: (directory: string) => Effect.Effect<InstanceHealth>
  readonly getAll: () => Effect.Effect<Record<string, InstanceHealth>>
  readonly set: (directory: string, health: InstanceHealth) => Effect.Effect<void>
  readonly remove: (directory: string) => Effect.Effect<void>
}

export class Service extends Context.Service<Service, Interface>()("@opencode/InstanceHealthStore") {}

export const layer: Layer.Layer<Service> = Layer.effect(
  Service,
  Effect.gen(function* () {
    const state = yield* Ref.make<Map<string, InstanceHealth>>(new Map())
    return Service.of({
      get: (directory) =>
        Ref.get(state).pipe(
          Effect.map((m) => m.get(directory) ?? { status: InstanceStatus.Booting, updatedAt: Date.now() }),
        ),
      getAll: () => Ref.get(state).pipe(Effect.map((m) => Object.fromEntries(m))),
      set: (directory, h) =>
        Ref.update(state, (m) => {
          const next = new Map(m)
          next.set(directory, h)
          return next
        }),
      remove: (directory) =>
        Ref.update(state, (m) => {
          const next = new Map(m)
          next.delete(directory)
          return next
        }),
    })
  }),
)
```

