}).pipe(Effect.withSpan("InstanceBootstrap"))
```

AFTER:
```typescript
const run = Effect.gen(function* () {
  const ctx = yield* InstanceState.context
  yield* Effect.logInfo("bootstrapping").pipe(Effect.annotateLogs("directory", ctx.directory))
  yield* config.get()
  yield* plugin.init()
  const services = [
    { name: "reference", svc: reference },
    { name: "lsp", svc: lsp },
    { name: "shareNext", svc: shareNext },
    { name: "format", svc: format },
    { name: "file", svc: file },
    { name: "fileWatcher", svc: fileWatcher },
    { name: "vcs", svc: vcs },
    { name: "snapshot", svc: snapshot },
    { name: "project", svc: project },
  ] as const
  const failures = yield* Ref.make<Array<{ name: string; cause: unknown }>>([])
  yield* Effect.all(
    services.map(({ name, svc }) =>
      svc.init().pipe(
        Effect.exit,
        Effect.flatMap((exit) =>
          Exit.isFailure(exit)
            ? Ref.update(failures, (a) => [...a, { name, cause: exit.cause }])
            : Effect.void,
        ),
      ),
    ),
    { concurrency: "unbounded" },
  ).pipe(Effect.withSpan("InstanceBootstrap.init"))
  const collected = yield* Ref.get(failures)
  if (collected.length > 0) {
    yield* Effect.sync(() =>
      GlobalBus.emit("event", {
        directory: ctx.directory,
        project: ctx.project.id,
        workspace: WorkspaceContext.workspaceID,
        payload: {
          type: "server.instance.degraded",
          properties: {
            directory: ctx.directory,
            failures: collected.map((f) => f.name),
          },
        },
      }),
    )
    return { allReady: false as const, failures: collected.map((f) => f.name) }
  }
  yield* Effect.sync(() =>
    GlobalBus.emit("event", {
      directory: ctx.directory,
      project: ctx.project.id,
      workspace: WorkspaceContext.workspaceID,
      payload: {
        type: "server.instance.loaded",
        properties: { directory: ctx.directory },
      },
    }),
  )
  return { allReady: true as const }
}).pipe(Effect.withSpan("InstanceBootstrap"))
```
Note: bootstrap.ts needs new imports: `Ref`, `Exit`, `GlobalBus`, `WorkspaceContext`.

### FIX 6: MODIFY instance-store.ts (6 hook points for health tracking)
