```
Place BEFORE `const ctx: InstanceContext = ...`

**Hook B — completeLoad (line 69-73, BEFORE Deferred.done):**
```typescript
const completeLoad = (directory: string, input: LoadInput, entry: Entry) =>
  Effect.gen(function* () {
    const exit = yield* Effect.exit(boot({ ...input, directory }))
    if (Exit.isFailure(exit)) {
      yield* instanceHealth.set(directory, { status: InstanceStatus.Failed, updatedAt: Date.now() })
      yield* instanceHealth.remove(directory)  // LEAK PATH 1 closed
      yield* removeEntry(directory, entry)
    } else {
      const result = exit.value  // BootstrapResult with .allReady
      if (result.allReady) {
        yield* instanceHealth.set(directory, { status: InstanceStatus.Ready, updatedAt: Date.now() })
      } else {
        yield* instanceHealth.set(directory, { status: InstanceStatus.Degraded, failures: result.failures, updatedAt: Date.now() })
      }
    }
    yield* Deferred.done(entry.deferred, exit).pipe(Effect.asVoid)
  })
```

**Hook C — disposeContext (line 89, before return):**
```typescript
const disposeContext = Effect.fn("InstanceStore.disposeContext")(function* (ctx: InstanceContext) {
  yield* Effect.logInfo("disposing instance").pipe(Effect.annotateLogs("directory", ctx.directory))
  yield* Effect.promise(() => runDisposers(ctx.directory))
  yield* emitDisposed({ directory: ctx.directory, project: ctx.project.id })
  yield* instanceHealth.set(ctx.directory, { status: InstanceStatus.Disposed, updatedAt: Date.now() })
  yield* instanceHealth.remove(ctx.directory)  // LEAK PATH 2 closed
})
```

**Hook D — disposeAllOnce (line 154, wrap with catchAll):**
```typescript
const disposeAllOnce = Effect.fnUntraced(function* () {
  yield* Effect.logInfo("disposing all instances")
  yield* Effect.forEach(
    [...cache.entries()],
    (item) =>
      Effect.gen(function* () {
        const exit = yield* Deferred.await(item[1].deferred).pipe(Effect.exit)
        if (Exit.isFailure(exit)) {
          yield* Effect.logWarning("instance dispose failed").pipe(
            Effect.annotateLogs({ key: item[0], cause: exit.cause }),
          )
          yield* instanceHealth.remove(item[0])  // LEAK PATH 3 closed
          yield* removeEntry(item[0], item[1])
          return
        }
        yield* disposeEntry(item[0], item[1], exit.value)
      }).pipe(Effect.catchAll(() => Effect.sync(() => { /* best-effort */ }))),  // SURVIVE individual failures
    { discard: true },
  )
})
```

**Hook E — Scope.addFinalizer (after disposeAll cached, before return Service.of):**
```typescript
yield* Effect.addFinalizer(() =>
  Effect.gen(function* () {
    const entries = yield* instanceHealth.getAll()
    yield* Effect.forEach(
      Object.keys(entries),
      (dir) => instanceHealth.remove(dir),
      { discard: true },
    )
  }).pipe(Effect.ignore),
)
```

