AFTER:
```typescript
const health = Effect.fn("GlobalHttpApi.health")(function* () {
  const registry = yield* Effect.serviceOption(HealthRegistry)
  const components = Option.isSome(registry) ? yield* registry.value.getAll() : undefined
  const instanceStore = yield* Effect.serviceOption(InstanceHealthStore.Service)
  let instance_healthy: boolean | undefined
  if (Option.isSome(instanceStore)) {
    const all = yield* instanceStore.value.getAll()
    const instances = Object.values(all)
    instance_healthy = instances.length === 0 ? undefined : instances.every((i) => i.status === InstanceStatus.Ready)
  }
  return { healthy: true as const, version: InstallationVersion, components, instance_healthy }
})
```
